export interface BezirkStat {
  bundesland: string;
  bundesland_code: string;
  bezirk_code: string;
  bezirk_name: string;
  is_capital: number;
  participants: number;
  reports: number;
}

export interface Participant {
  callsign: string;
  name: string | null;
  bezirk_code: string | null;
  bundesland_code: string | null;
  bundesland_name: string | null;
  report_count: number;
  suffixes: string | null;
}

export interface RepeaterStat {
  short_name: string;
  count: number;
}

export interface BlStat {
  bundesland: string;
  bundesland_code: string;
  participants: number;
  reports: number;
}

export interface Stats {
  totalParticipants: number;
  totalReports: number;
  perRepeater: RepeaterStat[];
  bezirkStats: BezirkStat[];
  blStats: BlStat[];
  participants: Participant[];
}

import { initDb } from './database.js';
import { runMigrations } from './schema.js';
import bcrypt from 'bcryptjs';

const db = initDb();
runMigrations(db);

console.log('Seeding database (idempotent)...');

const count = (table: string) => (db.prepare(`SELECT COUNT(*) as c FROM ${table}`).get() as any).c;

// ─── Bundesländer ───
const insertBl = db.prepare('INSERT OR IGNORE INTO bundeslaender (code, name, sort_order, is_international) VALUES (?, ?, ?, ?)');
const bundeslaender = [
  ['01', 'OE1 Wien', 1, 0],
  ['02', 'OE2 Salzburg', 2, 0],
  ['03', 'OE3 Niederösterreich', 3, 0],
  ['04', 'OE4 Burgenland', 4, 0],
