  ['16', 'Liechtenstein', 16, 1],
  ['17', 'Schweiz', 17, 1],
  ['18', 'Ungarn', 18, 1],
];
const insertBlMany = db.transaction(() => {
  for (const bl of bundeslaender) insertBl.run(...bl);
});
insertBlMany();
console.log(`  ✓ ${bundeslaender.length} Bundesländer`);

